def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if opp.get('hp', 0) > 2 and opp.get('budget', 0) > 0:
                    strong_prev.append(bid)

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    strongest_live_prev = max(strong_prev) if strong_prev else highest_prev

    tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if tightness < 0:
        tightness = 0.0
    if tightness > 1:
        tightness = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.55
    elif hp <= 4:
        urgency += 0.3
    elif hp <= 6:
        urgency += 0.12

    if no_water_days >= 2:
        urgency += 0.35
    elif no_water_days >= 1:
        urgency += 0.18

    urgency += 0.45 * tightness

    conservative = 16.0 + 18.0 * tightness
    pressure_bid = strongest_live_prev + 1.6 if strongest_live_prev > 0 else 0.0

    if hp >= 7 and no_water_days == 0 and supply >= 22:
        target = conservative
    elif urgency >= 0.95:
        target = max(62.0, pressure_bid, 0.88 * DAILY_SALARY + 28.0 * tightness)
    elif urgency >= 0.65:
        target = max(42.0 + 16.0 * tightness, min(pressure_bid, 96.0))
    else:
        target = max(conservative, min(pressure_bid, 58.0 + 10.0 * tightness))

    if day >= 8:
        target += 6.0 * tightness
        if hp <= 4:
            target += 8.0

    max_safe = budget
    if day < 9:
        reserve_days = 10 - day
        reserve = max(0.0, reserve_days * 8.0)
        max_safe = max(0.0, budget - reserve)
        if max_safe < 12.0:
            max_safe = min(budget, 12.0 + 8.0 * urgency)

    bid = min(budget, max_safe if max_safe > 0 else budget, target)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, max(68.0, pressure_bid, 84.0 + 18.0 * tightness)))

    if bid < 0:
        bid = 0.0
    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Alive opponents and immediate reaction from yesterday
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no one is alive, conserve
    if not alive_opps:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.35))

    # Collect yesterday bids and survival pressure proxy
    yesterday_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many units of water likely matter this day
    # (Only for scaling; actual allocation logic is handled by the game.)
    # supply is between 15 and 25, so water units are roughly 1-2.
    water_units = int(supply / float(WATER_REQ))  # int() to satisfy index rule
    if water_units < 1:
        water_units = 1

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))

    # Determine aggressiveness from yesterday's top bid.
    # If others paid very high, they likely believe water is scarce/critical.
    # We bid to compete but not to mirror the highest.
    if highest_prev_bid >= DAILY_SALARY * 1.0:
        # High competition: bid around 0.85 of the leader, slightly above a floor.
        base = highest_prev_bid * 0.85 + 2.0
    elif highest_prev_bid >= DAILY_SALARY * 0.75:
        base = highest_prev_bid * 0.75 + 1.5
    else:
        base = max(DAILY_SALARY * 0.45, highest_prev_bid + 1.0)

    # HP-based urgency: if low hp, increase bid.
    if my_hp <= 2:
        base *= 1.25
    elif my_hp <= 4:
        base *= 1.10

    # Supply scaling: at higher supply, we can bid slightly less.
    if supply >= 22.0:
        base *= 0.90
    elif supply <= 17.0:
        base *= 1.05

    # Budget cap: never exceed budget; keep some reserve for later days.
    # Reserve more when episode day is early.
    reserve_fraction = 0.35 if day <= 4 else 0.25 if day <= 7 else 0.15
    max_affordable = max(0.0, my_budget * (1.0 - reserve_fraction))

    bid = min(max_affordable, base)

    # Ensure non-negative and at least minimal participation if budget allows
    if bid < 0.0:
        bid = 0.0
    return float(bid)
